\begin {align*}
 \mathbb {P}(b_t = 0, z_t \mid  z_{t - 1}, s_t) &= (1 - \psi (s_t, z_{t - 1})) \cdot  \delta _{\{z_{t} = z_{t - 1}\}} \\
 \mathbb {P}(b_t = 1, z_t \mid  z_{t - 1}, s_t) &= \psi (s_t, z_{t - 1}) \cdot  \eta (z_t \mid  s_t)
.\end {align*}

\begin {align*}
\log  \mathbb {P}_{\theta }(\mathcal {H}, \xi ) &= \log  \left [p(s_{0})\delta _{\{b_{0} = 1\}}\eta _{\theta }(z_{0} \mid  s_{0}) \prod _{t=1}^{T - 1} \mathbb {P}_{\theta }(b_t, z_t \mid  z_{t - 1}, s_t) \prod _{t = 0}^{T - 1} \pi _{\theta }(a_t \mid  s_t, z_t) p(s_{t+1} \mid  s_t, a_t)\right ] \\
&= \log  p(s_{0})\delta _{\{b_{0} = 1\}} + \log \left [\eta _{\theta }(z_{0} \mid  s_{0}) \prod _{t=1}^{T - 1} \mathbb {P}_{\theta }(b_t, z_t \mid  z_{t - 1}, s_t) \prod _{t = 0}^{T - 1} \pi _{\theta }(a_t \mid  s_t, z_t) \right ] + \sum _{t=0}^{T-1} \log  \left [p(s_{t+1} \mid  s_t, a_t)\right ] \\
&= \underbrace {\log  p(s_{0})\delta _{\{b_{0} = 1\}} + \sum _{t=0}^{T-1} \log  \left [p(s_{t+1} \mid  s_t, a_t)\right ]}_{\text {independent of } \theta } + \log \left [\eta _{\theta }(z_{0} \mid  s_{0}) \prod _{t=1}^{T - 1} \mathbb {P}_{\theta }(b_t, z_t \mid  z_{t - 1}, s_t) \prod _{t = 0}^{T - 1} \pi _{\theta }(a_t \mid  s_t, z_t)\right ]
.\end {align*}

 egin {align*}

abla _{	heta } \log  \mathbb {P}_{	heta }(\mathcal {H}, \xi ) &= 
abla _{	heta } \left [ \log \left [\eta _{	heta }(z_{0} \mid  s_{0}) \prod _{t=1}^{T - 1} \mathbb {P}_{	heta }(b_t, z_t \mid  z_{t - 1}, s_t) \prod _{t = 0}^{T - 1} \pi _{	heta }(a_t \mid  s_t, z_t)ight ] ight ]\
&= 
abla _{	heta } \log \left [\eta _{	heta }(z_{0} \mid  s_{0})ight ] + \sum _{t=1}^{T - 1} 
abla _{	heta } \log \left [\mathbb {P}_{	heta }(b_t, z_t \mid  z_{t - 1}, s_t)ight ] + \sum _{t = 0}^{T - 1} 
abla _{	heta } \log  \left [\pi _{	heta }(a_t \mid  s_t, z_t)ight ].
\end {align*}

\begin {align*}
  \phi _t(z, b) &= \mathbb {P}(s_{0}, a_{0}, \ldots , s_{t}, z_{t} = z, b_{t} = b) \\
  \beta _t(z, b) &= \mathbb {P}(s_{t + 1}, a_{t + 1}, \ldots , s_{T} \mid  z_{t} = z, b_{t} = b),
.\end {align*}

\begin {align*}
  \phi _t(z, b) &= \mathbb {P}(s_t, a_t \mid  z, b) \sum _{(z', b')} \phi _{t - 1}(z', b') \mathbb {P}(z, b \mid  z', b') \\
  \beta _t(z, b) &= \sum _{(z', b')} \beta _{t + 1}(z', b') \mathbb {P}(s_{t + 1}, a_{t + 1} \mid  z', b')  \mathbb {P}(z', b' \mid  z, b)
.\end {align*}

\begin {align*}
  \mathbb {P}_{\theta }(z, b = 0 \mid  z') &= \delta _{\{z = z'\}} (1 - \psi _{\theta }(s_{t}, z')) \\
  \mathbb {P}_{\theta }(z, b = 1 \mid  z') &= \eta _{\theta }(z \mid  s_{t}) \psi _{\theta }(s_{t}, z')
.\end {align*}

\begin {align*}
  \phi _t(z, b) = \mathbb {P}_{\theta }(s_t, a_t \mid  z, b) \sum _{(z', b')} \phi _{t - 1}(z', b') \Big (&\eta _{\theta }(z \mid  s_{t}) \psi _{\theta }(s_{t}, z') \\
  &+ \delta _{\{z = z'\}} (1 - \psi _{\theta }(s_{t}, z'))\Big )
.\end {align*}

\begin {align*}
\mathbb {P}_{\theta }(s_t, a_t \mid  z) &= \pi _{\theta }(a_t \mid  s_t, z) p(s_t \mid  s_{t - 1}, a_{t - 1})
.\end {align*}

\begin {align*}
  \phi _t(z, b) = &\pi _{\theta }(a_t \mid  s_t, z) p(s_t \mid  s_{t - 1}, a_{t - 1}) \\
  &\times   \sum _{(z', b')} \phi _{t - 1}(z', b') \Big (\eta _{\theta }(z \mid  s_{t}) \psi _{\theta }(s_{t}, z') + \delta _{\{z = z'\}} (1 - \psi _{\theta }(s_{t}, z'))\Big )
.\end {align*}

\begin {align*}
  \mathbb {P}_{\theta }(z', b' = 0 \mid  z) &= \delta _{\{z' = z\}} (1 - \psi _{\theta }(s_{t + 1}, z)) \\
  \mathbb {P}_{\theta }(z', b' = 1 \mid  z) &= \eta _{\theta }(z' \mid  s_{t + 1}) \psi _{\theta }(s_{t + 1}, z)
.\end {align*}

\begin {align*}
\mathbb {P}_{\theta }(s_{t + 1}, a_{t + 1} \mid  z') &= \pi _{\theta }(a_{t + 1} \mid  s_{t + 1}, z') p(s_{t + 1} \mid  s_t, a_t)
.\end {align*}

\begin {align*}
\mathcal {L}_{\text {ELBO}}(\theta ) \approx  \sum _{t=1}^{T} \log  &p_{\theta }(\mathbf {a}_{t} \mid  \mathbf {s}_{t}) + D_{\text {KL}}(q_{\theta }(m_{t} \mid  \mathbf {x}_{1:t}) \parallel  p_{\theta }(m_{t} \mid  \mathbf {s}_{t})) \\ &+ D_{\text {KL}}(q_{\theta }(z_{t} \mid  m_{t}, \mathbf {x}_{1:T}, \mathbf {a}_{1:T}) \parallel  p(z_{t})) + D_{\text {KL}}(q_{\theta }(s_{t} \mid  z_{t}, \mathbf {x}_{t}) \parallel  p_{\theta }(s_{t} \mid  s_{t-1}, m_{t-1}))
.\end {align*}

fr:mainmatter.html:p:
Skill-conditioned GCIQL.
If we now define the analagous skill-conditioned GCIQL losses, we have
\begin {align}
  \mathcal {L}_{V}(\theta _{V}) &= \mathbb {E}_{(s_{t}, z_{t}, g) \sim  \mathcal {D}} \Big [L_{2}^{\tau }\big (Q_{\overline {\theta }_{Q}}(s_{t},z_{t},g) - V_{\theta _{V}}(s_{t},g)\big )\Big ] \\
  \mathcal {L}_{Q}(\theta _{Q}) &= \mathbb {E}_{(s_{t}, z_{t}, s_{t+\kappa }) \sim  \mathcal {D}} \Big [\big (r(s_{t}, z_{t}, g) + \gamma  V_{\overline {\theta }_{V}}(s_{t+\kappa }, g) - Q_{\theta _{Q}}(s_{t},z_{t},g) \big )^2\Big ]
\end {align}
This introduces a few changes and constraints on the final algorithm.

\kappa  is a random variable dependent on the termination condition of z.

It is not immediately obvious how we should design r(s_t, z_t, g).
Future states. For the first point, there are two options with trade-offs. In LOVE, they learn a model over trajectories that partitions them into unique skills. We can directly use this to get the intermediate s_{t + \kappa } just based off the termination output by the model.

This is the simplest approach and basically a generalization of HIQL to varying length skills, where they just use a state k steps away in the trajectory.

However, this approach would be limited on stitching datasets, where all of the trajectories are short.

The second approach, assuming we already have skills (given termination function), to perform better in the stitching setting is instead to learn a generative model over the state s_{t+\kappa }. Then we could just use  s_{t + \kappa } \sim  p(s_{t+\kappa } \mid  s_t, z_t) as our next state. There is new work on universal horizon models[chungOfflineReinforcementLearning2026] focused on this for n-step models. Alternatively, it seems there is work directly learning the value function for a sequence of skills [farebrotherCompositionalPlanningJumpy2026], but this seems to only work for a fixed (per skill) discount factor.


Reward. Here, I propose a modified reward function based on the observation that goal-conditioned policies work well for short-horizon goal-reaching. One of our skills is hardcoded to instead be a learned goal-conditioned policy \pi (a \mid  s, g) with associated value function V(s, g). Denote this skill as z_g. Then we can define the reward function as
\begin {align*}
  r(s, z, g) &= \begin {cases}
    1, & \text {if } z = z_g \text { and } V(s, g) < \epsilon  \\
    0, & \text {otherwise}
  \end {cases}
.\end {align*}


Note that it may be the case that the high-level policy learns to just choose z_g everytime, so we may want to penalize that decision somehow for (s,g) pairs with large V(s,g). Intuitively, this would end up with a higher-level policy that best utilizes the temporally-extended skills to reach the nearby region of g then concedes to the lower-level policy.

fr:frontmatter.fr:meta:
@article{jiangLearningOptionsCompression,
 title = {Learning {{Options}} via {{Compression}}},
 author = {Jiang, Yiding and Liu, Evan Zheran and Eysenbach, Benjamin and Kolter, J Zico and Finn, Chelsea},
 file = {/home/kellen/Downloads/papers/Learning Options via Compression - Jiang et al..pdf},
 langid = {english},
 abstract = {Identifying statistical regularities in solutions to some tasks in multi-task reinforcement learning can accelerate the learning of new tasks. Skill learning offers one way of identifying these regularities by decomposing pre-collected experiences into a sequence of skills. A popular approach to skill learning is maximizing the likelihood of the pre-collected experience with latent variable models, where the latent variables represent the skills. However, there are often many solutions that maximize the likelihood equally well, including degenerate solutions. To address this underspecification, we propose a new objective that combines the maximum likelihood objective with a penalty on the description length of the skills. This penalty incentivizes the skills to maximally extract common structures from the experiences. Empirically, our objective learns skills that solve downstream tasks in fewer samples compared to skills learned from only maximizing likelihood. Further, while most prior works in the offline multi-task setting focus on tasks with low-dimensional observations, our objective can scale to challenging tasks with high-dimensional image observations.}
}

